  /api/v1/saved-views:
    get:
      tags: [search]
      operationId: listSavedViews
      summary: "The caller's active saved views of one list plus the active views shared in the caller's organization (signed in; AUD reads and applies). A shared view of a transformation the caller cannot read is not listed. Owner's views first, then shared, each by name. ADR-0057 §4; REQ-S15-013."
      parameters:
        - { name: listKey, in: query, required: true, schema: { $ref: "#/components/schemas/SavedViewListKey" } }
        - { name: transformationId, in: query, required: false, description: "Views of this transformation and views for any transformation (transformationId null).", schema: { $ref: "#/components/schemas/Uuid" } }
        - $ref: "#/components/parameters/Cursor"
        - $ref: "#/components/parameters/Limit"
      responses:
        "200":
          description: "OK."
          content:
            application/json:
              schema: { $ref: "#/components/schemas/SavedViewPage" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "429": { $ref: "#/components/responses/RateLimited" }
    post:
      tags: [search]
      operationId: createSavedView
      summary: "Save a personal view of a list: columns, filters and sort, optionally as the default (saved_view.manage; every role except AUD). Keys are checked against the list registry. Setting isDefault clears the owner's previous default for the list. Audit saved_view.created. 404 transformation not readable; 409 saved_view.name_taken; 422 saved_view.unknown_key. ADR-0057 §4."
      security:
        - sessionCookie: []
          csrfToken: []
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: "#/components/schemas/SavedViewCreate" }
