          content:
            application/json:
              schema: { $ref: "#/components/schemas/AssistantMessagePostResult" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "409": { $ref: "#/components/responses/VersionConflict" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "428": { $ref: "#/components/responses/PreconditionRequired" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/assistant/suggestions/{suggestionId}/to-draft:
    parameters:
      - $ref: "#/components/parameters/AssistantSuggestionId"
    post:
      tags: [assistant]
      operationId: takeAssistantSuggestionToDraft
      summary: "Mark one's own charter or decision-brief suggestion as taken and return a form-draft prefill (assistant.use plus the target's write permission: charter.edit for charter, executive_decision.create for T16, re-checked at commit; transformation.read, else 404; If-Match = the suggestion). Writes nothing outside assistant_suggestion: the caller then creates the draft with createFormDraft, and a human edits, saves and submits the record. Audit assistant_suggestion.taken_to_draft. 422 assistant.suggestion_not_draftable, assistant.suggestion_already_taken. ADR-0059 §6; REQ-S17-008."
      security:
        - sessionCookie: []
          csrfToken: []
      parameters:
        - $ref: "#/components/parameters/IfMatch"
      responses:
        "200":
          description: "OK."
          headers:
            ETag: { $ref: "#/components/headers/ETag" }
          content:
            application/json:
              schema: { $ref: "#/components/schemas/AssistantTakeToDraftResult" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "404": { $ref: "#/components/responses/NotFound" }
        "409": { $ref: "#/components/responses/VersionConflict" }
        "422": { $ref: "#/components/responses/BusinessRule" }
        "428": { $ref: "#/components/responses/PreconditionRequired" }
        "429": { $ref: "#/components/responses/RateLimited" }
EOF
cat > $TMPDIR/params.yaml <<'EOF'
    AssistantConversationId:
      name: conversationId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }
    AssistantSuggestionId:
      name: suggestionId
      in: path
      required: true
      schema: { $ref: "#/components/schemas/Uuid" }
EOF
